#!/usr/bin/env python3
"""Pull the OEM module-signing certificate out of a stock boot image's kernel Image.
The kernel embeds its trusted X.509 certificates in the image; the one whose subject is
"Build time autogenerated kernel key" is the key the vendor's prebuilt .ko files are signed with.
Usage: extract_oem_cert.py <boot.img> <out.der> [out.pem]   (openssl is needed for the .pem)"""
import re, struct, subprocess, sys
boot, der = sys.argv[1], sys.argv[2]; pem = sys.argv[3] if len(sys.argv) > 3 else None
d = open(boot, 'rb').read(); assert d[:8] == b'ANDROID!'
ks = struct.unpack_from('<I', d, 8)[0]; k = d[4096:4096 + ks]
found = None
for m in re.finditer(rb'\x30\x82[\x00-\x0f][\x00-\xff]\x30\x82', k):
    o = m.start(); L = struct.unpack('>H', k[o+2:o+4])[0]; blob = k[o:o+4+L]
    if b'Build time autogenerated kernel key' in blob:
        found = (o, blob); break
assert found, 'no build-time kernel key certificate found'
open(der, 'wb').write(found[1]); print(f'cert at Image offset {found[0]:#x}, {len(found[1])} bytes -> {der}')
if pem:
    subprocess.check_call(['openssl', 'x509', '-inform', 'der', '-in', der, '-out', pem]); print('pem ->', pem)
